void dfs(int idx, int64 remaining, int64 currentX) {
    if (remaining == 1) {
        if (currentX > 0) answer++;
        return;
    }
    if (idx == (int)primes.size()) return;

    // Option: skip this prime as a base for p^k
    dfs(idx + 1, remaining, currentX);

    int64 p = primes[idx];
    // Try k >= 1 while σ(p^k) divides remaining
    int64 pk = p;
    for (int k = 1; ; ++k) {
