        int64 num = pk * p - 1;
        int64 den = p - 1;
        if (num % den != 0) break;
        int64 sigma = num / den;
        if (sigma == 0 || remaining % sigma != 0) break;
        if ((double)currentX * pk > 1e18) break;
        dfs(idx + 1, remaining / sigma, currentX * pk);
        if ((double)pk * p > 1e18) break;
        pk *= p;
    }
