// For a prime p and exponent e, sigma(p^e) = (p^{e+1}-1)/(p-1)
// We'll recursively build all possible sigma(p^e) factors whose product is A.
// For each factorization of A into sigma(p_i^{e_i}), we reconstruct x = product p_i^{e_i}.

long long ans = 0;

// Precompute possible sigma(p^e) for a given prime p, not exceeding limit
void gen_sigma_p(long long p, long long limit, vector<long long> &vals, vector<int> &exps) {
    long long pe = 1;
    long long sigma = 1; // sigma(p^0)
    int e = 0;
    while (sigma <= limit) {
        vals.push_back(sigma);
        exps.push_back(e);
        // next exponent
        if (limit / p < pe) break;
        pe *= p;
        sigma += pe;
        ++e;
    }
}

// DFS over primes to factor A multiplicatively into sigma(p^e)
void dfs(int idx, long long curA, long long curX, long long lastPrime) {
    if (curA == 1) {
        if (curX > 1) ans++; // x must be positive; sigma(1)=1, but x=1 gives sigma=1
        return;
    }
    if (idx >= (int)primes.size()) return;

    for (int i = idx; i < (int)primes.size(); ++i) {
        long long p = primes[i];
        if (p < lastPrime) continue; // ensure non-decreasing primes to avoid duplicates
        if (p - 1 > curA) break; // minimal sigma(p^1)=1+p > curA if p-1>curA? but cheap bound
        vector<long long> vals;
        vector<int> exps;
        gen_sigma_p(p, curA, vals, exps);
