// We need to count positive integers x such that sum of divisors sigma(x) = A.
// A up to 1e12. We'll generate all possible x by factorizing A and using
// multiplicative structure of sigma function.

// For a prime power p^k, sigma(p^k) = (p^{k+1}-1)/(p-1).
// For x = product p_i^{e_i}, sigma(x) = product sigma(p_i^{e_i}).
// So we need to factor A into factors each of which is of the form sigma(p^k).

// Precompute primes up to 1e6 (since sqrt(1e12) = 1e6).
// For each prime p, generate sigma(p^k) while it doesn't exceed A.
// Then recursively factor A as product of these sigma values, ensuring
// increasing primes to avoid duplicates.

vector<long long> primes;

void sieve(int n = 1000000) {
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; 1LL * i * i <= n; ++i)
        if (is_prime[i])
            for (int j = i * i; j <= n; j += i)
                is_prime[j] = false;
    for (int i = 2; i <= n; ++i)
        if (is_prime[i]) primes.push_back(i);
}

long long A;
long long answer = 0;

// recursive search: remaining product 'rem', last prime index 'idx',
// and current x value 'curX'. We ensure primes are used in increasing order.
void dfs(long long rem, int idx, long long curX) {
    if (rem == 1) {
        // sigma(curX) == A
        ++answer;
        return;
    }

    // Try using prime powers starting from primes[idx]
    for (int i = idx; i < (int)primes.size(); ++i) {
        long long p = primes[i];

        // For sigma(p^k) = (p^{k+1}-1)/(p-1) to divide rem, it must be <= rem.
        // Also, p^{2} already > rem*(p-1)+1 implies no k>=1 possible.
        if (p > rem + 1) break; // heuristic pruning

        long long pk = 1;
        long long sigma_pk = 1; // sigma(p^0)
        // We need k>=1, so first step will make pk=p, sigma_pk = 1 + p + ... + p^k
        for (int k = 1;; ++k) {
            if (pk > (A / p)) break; // avoid overflow, pk *= p below
            pk *= p;
            // sigma(p^k) = (p^{k+1}-1)/(p-1)
            // We can update incrementally: sigma_pk = sigma(p^{k-1}) + p^k
            sigma_pk += pk;
            if (sigma_pk > rem) break;
            if (rem % sigma_pk == 0) {
                // multiply x by p^k
                if (curX > (A / pk)) continue; // avoid overflow and impossible x
                dfs(rem / sigma_pk, i + 1, curX * pk);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> A)) return 0;

    sieve();

    // Special case: x = 1 => sigma(1) = 1
    if (A == 1) {
        cout << 1 << '\n';
        return 0;
    }

    dfs(A, 0, 1);

    cout << answer << '\n';
    return 0;
}
