#include <bits/stdc++.h>
using namespace std;

/*
We need to count positive integers x such that sum of divisors σ(x) = A.
Let A be given. For each x, σ(x) = product over primes p^k || x of (p^{k+1}-1)/(p-1).

We will generate all possible x by backtracking over prime powers, ensuring:
- σ(x) does not exceed A
- x does not exceed A (since σ(x) >= x+1 for x>1, so x < A)
We use primes in increasing order to avoid duplicates and ensure unique factorization.

We precompute primes up to 1e6 (enough since A ≤ 1e12, and smallest prime factor
of any remaining >1 part will be >1e6, but we handle that via a final check).
*/

const long long A_MAX = (long long)1e12;
vector<int> primes;

void sieve(int n = 1000000) {
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * 1LL * i <= n; ++i)
        if (is_prime[i])
            for (int j = i * i; j <= n; j += i)
                is_prime[j] = false;
    for (int i = 2; i <= n; ++i)
        if (is_prime[i]) primes.push_back(i);
}

long long A;
long long ans = 0;

void dfs(int idx, long long curX, long long curSigma, long long lastPrime) {
    if (curSigma == A) {
        if (curX > 0) ans++;
        return;
    }
    if (curSigma > A) return;
    if (idx >= (int)primes.size()) return;

    for (int i = idx; i < (int)primes.size(); ++i) {
        long long p = primes[i];
        if (p < lastPrime) continue; // ensure non-decreasing primes
        // Try multiplying by p^k
        long long pk = p;
        long long newX = curX;
        long long newSigma = curSigma;
        long long term = 1; // p^0
        long long sumTerm = 1; // 1 + p + ... + p^k

        // We will increase exponent k step by step
        while (true) {
            if (newX > A / p) break; // x would exceed A
            newX *= p;
            term *= p;
            sumTerm += term;
            if (sumTerm > (A / curSigma)) break; // sigma would exceed A
            newSigma = curSigma * sumTerm;
            if (newSigma > A) break;
            dfs(i + 1, newX, newSigma, p);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> A)) return 0;

    sieve();

    // Handle x = 1 separately: σ(1) = 1
    if (A == 1) {
        cout << 1 << "\n";
        return 0;
    }

    // Start DFS with x=1, σ=1
    dfs(0, 1, 1, 2);

    cout << ans << "\n";
    return 0;
}
