#include <bits/stdc++.h>
using namespace std;

// Problem: Count number of positive integers x such that sum of divisors σ(x) = A
// A up to 1e12. We use multiplicativity and structure of σ(p^k).

// Compute integer power safely (with overflow check against limit)
bool pow_le(long long base, int exp, long long limit, long long &res) {
    res = 1;
    while (exp) {
        if (exp & 1) {
            if (base != 0 && res > limit / base) return false;
            res *= base;
        }
        exp >>= 1;
        if (exp) {
            if (base != 0 && base > limit / base) return false;
            base *= base;
        }
    }
    return true;
}

// Factorization of A (<=1e12) by trial division
vector<pair<long long,int>> factorize(long long n) {
    vector<pair<long long,int>> f;
    for (long long p = 2; p * p <= n; ++p) {
        if (n % p == 0) {
            int c = 0;
            while (n % p == 0) {
                n /= p;
                ++c;
            }
            f.push_back({p,c});
        }
       }
    if (n > 1) f.push_back({n,1});
    return f;
}

// For given prime p and target sum S, find all exponents k>=1 such that σ(p^k)=S
// σ(p^k) = (p^{k+1}-1)/(p-1). We solve for k by trying small k until σ exceeds S.
vector<int> exponents_for_prime_sum(long long p, long long S) {
    vector<int> res;
    // σ(p^k) grows quickly; k won't be large.
    long long pk = 1;
    for (int k = 1; ; ++k) {
        if (!pow_le(p, k+1, LLONG_MAX, pk)) break;
        long long num = pk - 1;
        long long denom = p - 1;
        if (num % denom != 0) continue;
        long long sigma = num / denom;
        if (sigma == S) res.push_back(k);
        if (sigma >= S) break;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long A;
    if (!(cin >> A)) return 0;

    if (A == 1) {
        // σ(1)=1 only
        cout << 1 << '\n';
        return 0;
    }

    // Factorize A to generate candidate σ(p^k) factors
    auto fac = factorize(A);
    int m = fac.size();

    // For each factor A_i = p_i^{e_i}, we need to consider all ways to split it
    // into product of σ(p^k) terms. But σ(p^k) are not prime powers generally.
    // Instead, we search over primes p and exponents k such that σ(p^k) divides A.

    // Precompute all σ(p^k) divisors of A and their corresponding (p,k).
    // We'll store mapping from sigma value to list of (p,k).
    unordered_map<long long, vector<pair<long long,int>>> sigma_map;

    // Enumerate primes up to some bound: since σ(p) = 1+p divides A, p <= A-1.
    // But we can restrict: if σ(p^1)=1+p divides A, then p <= A-1 but A<=1e12, primes up to 1e6 are enough
    // because p^2 already huge. We'll just generate primes up to 1e6.
    const int LIMIT = 1000000;
    vector<int> primes;
    vector<bool> is_comp(LIMIT+1,false);
    for (int i=2;i<=LIMIT;++i){
        if(!is_comp[i]){
            primes.push_back(i);
            if((long long)i*i<=LIMIT)
                for(int j=i*i;j<=LIMIT;j+=i) is_comp[j]=true;
        }
    }

    // For each prime p, compute σ(p^k) while <=A and record if divides A
    for (int p: primes) {
        long long pk = 1;
        for (int k = 1; ; ++k) {
            if (!pow_le(p, k+1, LLONG_MAX, pk)) break;
            long long num = pk - 1;
            long long denom = p - 1;
            if (num % denom != 0) continue;
            long long sigma = num / denom;
            if (sigma > A) break;
            if (A % sigma == 0) {
                sigma_map[sigma].push_back({p,k});
            }
        }
    }

    // Also handle case where p itself may be >1e6 but σ(p)=1+p divides A.
    // For each divisor d of A, if d-1 is prime >1e6, then σ(p)=d.
    // Enumerate divisors of A.
    vector<long long> divisors;
    function<void(int,long long)> gen = [&](int idx,long long cur){
        if(idx==(int)fac.size()){
            divisors.push_back(cur);
            return;
        }
        auto [p,e]=fac[idx];
        long long val=1;
        for(int i=0;i<=e;++i){
            gen(idx+1,cur*val);
            val*=p;
        }
    };
    gen(0,1);
    sort(divisors.begin(),divisors.end());
    divisors.erase(unique(divisors.begin(),divisors.end()),divisors.end());

    auto is_prime_large = [&](long long n)->bool{
        if(n<=1) return false;
        if(n<=LIMIT) return !is_comp[n];
        for(long long i=2;i*i<=n;++i)
            if(n%i==0) return false;
        return true;
    };

    for(long long d: divisors){
        if(d<=2) continue;
        long long p = d-1;
        if(p>LIMIT && is_prime_large(p)){
            sigma_map[d].push_back({p,1});
        }
    }

    // Now we need to count number of ways to write A as product of σ(p_i^{k_i})
    // with distinct primes p_i, and then each such representation corresponds to
    // exactly one x = product p_i^{k_i}.
