// Function to compute sum of divisors of x
long long sumDiv(long long x) {
    long long res = 0;
    for (long long d = 1; d * d <= x; ++d) {
        if (x % d == 0) {
            res += d;
            if (d * d != x) res += x / d;
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long A;
    if (!(cin >> A)) return 0;

    // J(x) = sum of divisors of x = A
    // We need to count x such that sumDiv(x) = A.
    // Upper bound for x: for x >= 2, sumDiv(x) >= x + 1, so x <= A - 1
    // Also x is positive integer.
    long long countSolutions = 0;

    // x = 1: sumDiv(1) = 1
    if (A == 1) {
        cout << 1 << '\n';
        return 0;
    }

    // For x >= 2, x <= A - 1
    for (long long x = 2; x <= A - 1; ++x) {
        if (sumDiv(x) == A) ++countSolutions;
    }

    cout << countSolutions << '\n';
    return 0;
